// <work-composer> — the conversation input. Emits an intent rather than wiring
// to a transport itself: on submit it dispatches a `work-intent` CustomEvent
// (bubbles, composed) carrying the typed text; the thread / host decides what
// to do with it (append a turn, call inference over this.host, …). This keeps
// the element transport-agnostic — same element, any provider behind the Dock.
//
// State (the `state` attribute, reflected so :host([state=…]) themes it):
//   idle      — ready for input
//   thinking  — the agent is working (animated indicator, input locked)
//   streaming — a reply is streaming in (animated indicator, input locked)
//
// Usage:
//   <work-composer placeholder="Message the agent…"></work-composer>
//   composer.addEventListener("work-intent", (e) => { … e.detail.text … });
//   composer.setAttribute("state", "thinking");  // host flips it while busy
import { WbElement, html, css, define } from "../../core/element.js";
import { ref, createRef } from "lit/directives/ref.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";

const VARIANTS = defineVariants({
  state: { options: ["idle", "thinking", "streaming"], default: "idle" },
});

export class WbComposer extends WbElement {
  static variants = VARIANTS;
  static props = [...variantAttrs(VARIANTS), "placeholder", "disabled"];

  _ta = createRef();

  static styles = css`
    :host { display: block; font-family: var(--work-font); color: var(--work-fg); }
    .composer {
      display: flex; align-items: flex-end; gap: var(--work-space-2);
      border: 1.5px solid var(--work-border-strong);
      border-radius: var(--work-radius-lg);
      background: var(--work-surface);
      padding: var(--work-space-2) var(--work-space-2) var(--work-space-2) var(--work-space-4);
      transition: border-color var(--work-dur) var(--work-ease), box-shadow var(--work-dur) var(--work-ease);
    }
    .composer:focus-within { border-color: var(--work-brand); box-shadow: 0 0 0 3px var(--work-ring); }
    textarea {
      flex: 1; resize: none; border: 0; outline: 0; background: none;
      font: var(--work-text)/1.5 var(--work-font); color: var(--work-fg);
      padding: var(--work-space-2) 0; max-height: 180px;
    }
    textarea::placeholder { color: var(--work-fg-subtle); }
    .send {
      display: inline-grid; place-items: center; width: 34px; height: 34px; flex: none;
      border: 0; border-radius: var(--work-radius); cursor: pointer;
      background: var(--work-brand); color: var(--work-on-brand);
      transition: filter var(--work-dur) var(--work-ease), opacity var(--work-dur) var(--work-ease);
    }
    .send:hover { filter: brightness(1.06); }
    .send:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--work-ring); }
    .send svg { width: 16px; height: 16px; }

    /* busy states: lock input, show a live indicator in place of the icon */
    :host([state="thinking"]) textarea,
    :host([state="streaming"]) textarea,
    :host([disabled]) textarea { pointer-events: none; opacity: .6; }
    :host([state="thinking"]) .composer,
    :host([state="streaming"]) .composer { border-color: var(--work-brand); }

    .dots { display: inline-flex; gap: var(--work-space-3px); }
    .dots i { width: 5px; height: 5px; border-radius: 50%; background: currentColor;
      animation: wb-pulse 1s var(--work-ease) infinite; }
    .dots i:nth-child(2) { animation-delay: .15s; }
    .dots i:nth-child(3) { animation-delay: .3s; }
    @keyframes wb-pulse { 0%,80%,100% { opacity: .25; transform: scale(.8); } 40% { opacity: 1; transform: scale(1); } }

    .status { font: 600 11px var(--work-font-mono); letter-spacing: .06em;
      text-transform: uppercase; color: var(--work-fg-muted);
      padding: 0 var(--work-space-2) var(--work-space-1); height: 0; overflow: hidden;
      transition: height var(--work-dur); }
    :host([state="thinking"]) .status,
    :host([state="streaming"]) .status { height: 18px; }
    .status .dots { color: var(--work-brand); vertical-align: middle; margin-left: var(--work-space-1); }
  `;

  /** Programmatic value. */
  get value() {
    return this._ta.value?.value || "";
  }
  set value(v) {
    if (this._ta.value) this._ta.value.value = v;
  }

  get busy() {
    return this.attr("state", "idle") !== "idle" || this.boolAttr("disabled");
  }

  _submit() {
    if (this.busy) return;
    const ta = this._ta.value;
    const text = (ta?.value || "").trim();
    if (!text) return;
    this.dispatchEvent(
      new CustomEvent("work-intent", {
        bubbles: true,
        composed: true,
        detail: { action: "send", text },
      }),
    );
    if (ta) ta.value = "";
  }

  _onKeydown(e) {
    // Enter submits; Shift+Enter inserts a newline.
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      this._submit();
    }
  }

  render() {
    const ph = this.attr("placeholder", "Message the agent…");
    const state = this.attr("state", "idle");
    const label = state === "thinking" ? "Thinking" : state === "streaming" ? "Streaming" : "";
    const dots = html`<span class="dots"><i></i><i></i><i></i></span>`;
    const sendIcon = this.busy
      ? dots
      : html`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 2 11 13M22 2l-7 20-4-9-9-4 20-7z"></path></svg>`;
    return html`
      <div class="status">${label}${label ? dots : ""}</div>
      <div class="composer">
        <textarea ${ref(this._ta)} part="input" rows="1" placeholder=${ph}
          tabindex=${this.busy ? "-1" : "0"} @keydown=${this._onKeydown}></textarea>
        <button class="send" part="send" aria-label="Send" ?disabled=${this.busy} @click=${this._submit}>${sendIcon}</button>
      </div>`;
  }
}

define("work-composer", WbComposer);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP), or `kernel` (oql.wasm) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}
